/* Intermediate7: access patterns, immutable primary keys and verified paused-writer migration. */
(function () {
  const N=AG.aws.n,clone=x=>JSON.parse(JSON.stringify(x)),file=x=>({content:JSON.stringify(x,null,2)});
  const wrap=s=>'<div class="tbl-wrap">'+s+'</div><p class="muted">Phone par baaki columns dekhne ke liye table ko side mein swipe karo.</p>';
  const rows=()=>[101,102,103].map((id,i)=>({cartId:'cart-'+id,status:'active',sellerId:i===1?'seller-2':'seller-1',updatedAt:1800000000+i,expiresAt:1900000000+i,total:499,version:1}));
  const fresh=()=>({cartId:'cart-104',status:'active',sellerId:'seller-1',updatedAt:1800000004,expiresAt:1900000004,total:499,version:1});
  const typed=row=>Object.fromEntries(Object.entries(row).map(([k,v])=>[k,typeof v==='number'?{N:String(v)}:{S:v}]));
  const seed=()=>({region:'ap-south-1',tables:[{name:'carts-v1',tableId:'11111111-1111-4111-8111-111111111111',partitionKey:'status',sortKey:'cartId',attributeTypes:{status:'S',cartId:'S'},billing:'PAY_PER_REQUEST',status:'ACTIVE',items:rows()}]});
  const tab=(s,name='carts-v2')=>(s.account.tables||[]).find(t=>t.name===name);
  const equalRows=(a,b)=>Array.isArray(a)&&a.length===b.length&&b.every(row=>a.some(x=>Object.keys(x).length===Object.keys(row).length&&Object.entries(row).every(([k,v])=>x[k]===v)));
  function preserved(s){const t=tab(s,'carts-v1');return !!t&&t.tableId==='11111111-1111-4111-8111-111111111111'&&t.partitionKey==='status'&&t.sortKey==='cartId'&&t.billing==='PAY_PER_REQUEST'&&equalRows(t.items,rows())&&(s.account.tables||[]).length===2;}
  function schemaReady(s){const t=tab(s);return !!t&&t.partitionKey==='cartId'&&!t.sortKey&&t.attributeTypes?.cartId==='S'&&t.billing==='PAY_PER_REQUEST'&&t.status==='ACTIVE';}
  function indexReady(s){const t=tab(s),i=t?.gsis?.find(i=>i.name==='bySeller');return !!i&&t.gsis.length===1&&i.partitionKey==='sellerId'&&i.sortKey==='updatedAt'&&i.projection.ProjectionType==='ALL'&&i.status==='ACTIVE'&&t.attributeTypes.sellerId==='S'&&t.attributeTypes.updatedAt==='N';}
  function resultReady(s){const t=tab(s),r=t?.lastRead;return !!r&&r.op==='query'&&r.index==='bySeller'&&!r.consistent&&!r.hasMore&&r.revision===(t.revision||0)&&equalRows(r.items,[rows()[0],rows()[2],fresh()]);}
  const SOLUTION=[
    'aws dynamodb create-table --table-name carts-v2 --attribute-definitions AttributeName=cartId,AttributeType=S --key-schema AttributeName=cartId,KeyType=HASH --billing-mode PAY_PER_REQUEST',
    'aws dynamodb wait table-exists --table-name carts-v2',
    'aws dynamodb batch-write-item --request-items file://backfill.json',
    'aws dynamodb update-table --table-name carts-v2 --attribute-definitions AttributeName=sellerId,AttributeType=S AttributeName=updatedAt,AttributeType=N --global-secondary-index-updates file://seller-index.json',
    'aws dynamodb wait table-exists --table-name carts-v2',
    'aws dynamodb describe-table --table-name carts-v2',
    'aws dynamodb update-continuous-backups --table-name carts-v2 --point-in-time-recovery-specification PointInTimeRecoveryEnabled=true,RecoveryPeriodInDays=35',
    'aws dynamodb update-time-to-live --table-name carts-v2 --time-to-live-specification Enabled=true,AttributeName=expiresAt',
    'aws dynamodb describe-time-to-live --table-name carts-v2',
    "aws dynamodb put-item --table-name carts-v2 --item file://new-cart.json --condition-expression 'attribute_not_exists(cartId)'",
    "aws dynamodb put-item --table-name carts-v2 --item file://duplicate-cart.json --condition-expression 'attribute_not_exists(cartId)'",
    `aws dynamodb query --table-name carts-v2 --index-name bySeller --key-condition-expression '#s = :s' --expression-attribute-names '{"#s":"sellerId"}' --expression-attribute-values '{":s":{"S":"seller-1"}}'`
  ];
  const TASKS=[
    {text:'Purane teen carts aur unke attributes carts-v1 mein bache; sirf zaroori v2 joda',check:preserved},
    {text:'Alag carts-v2: cartId String HASH, sort key nahi, PAY_PER_REQUEST, ACTIVE',check:schemaReady},
    {text:'Teeno backfill kiye carts + sahi cart-104; koi attribute ya item kam/zyada nahi',check:s=>equalRows(tab(s)?.items,[...rows(),fresh()])},
    {text:'bySeller GSI ACTIVE: sellerId String HASH + updatedAt Number RANGE, ALL projection',check:indexReady},
    {text:'PITR on, 35 din ki recovery window; TTL expiresAt ka status ENABLED',check:s=>!!tab(s)?.pitr?.enabled&&tab(s).pitr.days===35&&tab(s).ttl?.attribute==='expiresAt'&&tab(s).ttl.status==='ENABLED'},
    {text:'Duplicate cart-104 (total 0) condition se reject hua aur pehle wala total 499 bacha raha',check:s=>{const t=tab(s),c=t?.lastCondition;return !!c&&!c.applied&&c.key.cartId==='cart-104'&&c.attempted.total===0&&c.existing.total===499&&c.revision===(t.revision||0)&&t.items.some(x=>x.cartId==='cart-104'&&x.total===499);}},
    {text:'Aakhri GSI query bilkul teen seller-1 carts lautati hai, aur pages nahi',check:resultReady}
  ];
  const FILES={'backfill.json':file({'carts-v2':rows().map(row=>({PutRequest:{Item:typed(row)}}))}),'seller-index.json':file([{Create:{IndexName:'bySeller',KeySchema:[{AttributeName:'sellerId',KeyType:'HASH'},{AttributeName:'updatedAt',KeyType:'RANGE'}],Projection:{ProjectionType:'ALL'}}}]),'new-cart.json':file(typed(fresh())),'duplicate-cart.json':file(typed({...fresh(),total:0}))};
  function Q(q,correct,wrong,answer,explain){const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain};}
  function plan(k){const readUnits=Math.ceil(k.kb/4)*.5,writeUnits=Math.ceil(k.kb),baseR=k.reads*readUnits,baseW=k.writes*writeUnits,peakR=baseR*k.peak,peakW=baseW*k.peak,scale=[1,k.peak,k.peak/0.7][k.capacity],rcu=Math.ceil(baseR*scale),wcu=Math.ceil(baseW*scale),ondemand=(baseR*.000000125+baseW*.000000625)*3600*(22+2*k.peak)*30,provisioned=(rcu*.00013+wcu*.00065)*720,bestProvisioned=(Math.ceil(peakR)*.00013+Math.ceil(peakW)*.00065)*720,cheapest=Math.min(ondemand,bestProvisioned),cost=k.mode===0?ondemand:provisioned,capacityOK=k.mode===0||rcu>=peakR&&wcu>=peakW,share=k.key===0?1:.1,hot=peakR*share>3000||peakW*share>1000,valid=k.reads>=300&&k.writes>=150&&k.kb>=5&&k.peak>=3;return {baseR,baseW,peakR,peakW,rcu,wcu,ondemand,provisioned,cheapest,cost,hot,capacityOK,valid,ok:valid&&!hot&&capacityOK&&cost<=cheapest+.001};}
  AG.registerLevels('intermediate',[{
    id:'dynamodb',icon:'📊',title:'DynamoDB: access patterns, safe migration aur sahi data',badge:'NoSQL Nayak',
    objectives:['<b>Model:</b> pehle access patterns; primary key vs index','<b>Capacity:</b> round kiye read/write units, hot keys aur aaj ke daam','<b>Consistency:</b> table/LSI vs GSI; Query vs Scan','<b>Sahi data:</b> conditional writes aur atomic transactions','<b>Operations:</b> check kiya backfill, PITR, TTL aur replicas ke trade-offs','<b>Chunav:</b> DynamoDB vs SQL, S3 aur cache'],
    hook:{when:'SHOPKARO · DESH BHAR KI MAHASALE KE CARTS · COURSE KI KAHANI (FICTIONAL)',title:'“Table mein capacity bachi hai, phir bhi cart writes throttle kyun ho rahi hain?”',text:'ShopKaro ki 8 logon ki team carts ko bheed wale SQL raaste se DynamoDB par le ja rahi hai. Ravi ne status ko HASH aur cartId ko RANGE banaya; zyaadatar requests active carts par aati hain. Sale ke time ka data dikhata hai ki traffic ek partition par jama ho raha hai. Neha ko chahiye: behtar key, safe migration, aur saboot ki retry kisi cart ko overwrite nahi karegi. Sirf NoSQL chun lene se access pattern theek nahi hota.'},
    steps:[
      {q:'Table, item aur primary key ka exact model kya hai?',analogy:'Almirah ki drawer ka label partition key jaisa hai; drawer ke andar files ko order mein lagane wala label sort key jaisa. Poora pata = drawer + file. Storage ke andar shelf asal mein kaise lagi hai, yeh analogy se pakka nahi hota.',body:'<p>Table items rakhti hai, jinke non-key attributes badal sakte hain. Primary key ya toh sirf HASH hoti hai, ya HASH + RANGE; poori key unique hoti hai. Composite key mein kai items ka HASH same ho sakta hai, bas RANGE alag ho. Item ki limit 400 KB hai, jisme UTF-8 attribute names aur values dono gine jaate hain.</p>',points:['carts-v1 mein status + cartId hai. active/cart-101 aur active/cart-102 alag items hain. GetItem mein dono key hisse sahi S/N type ke saath dene padte hain. S = String; N wire par decimal string hota hai.','Primary key ka schema badal nahi sakta. UpdateTable status ko cartId mein nahi badal sakta. Nayi table banao, data mila kar migrate karo aur safe tarike se cutover karo; rollback ka raasta rakho.','Same logical partition key items ka ek group banati hai; asli physical partition kahan hai aur kab split ho, yeh service sambhalti hai. Zyada alag keys tabhi madad karti hain jab traffic bhi bata ho; ek bahut popular cart phir bhi hot ho sakta hai.'],code:`aws dynamodb get-item --table-name carts-v1 --key '{"status":{"S":"active"},"cartId":{"S":"cart-101"}}'`,asli:'Kaam: schema se pehle teen access patterns likho: ID se cart, time ke hisaab se seller ke carts, aur bina overwrite naya cart. Terminal ruke hue writers wale fixture se shuru hota hai, isliye diya gaya teen-item backfill pakka rehta hai.'},
      {q:'Access patterns pehle kyun? Single-table design kab kaam ka hai?',analogy:'Courier ka routing map parcels aane se pehle banta hai. Har delivery ke baad saare parcels scan karna achha lookup nahi. Ek warehouse ya alag-alag warehouses: yeh team ki boundaries aur delivery routes se tay karo.',body:wrap('<table><tr><th>Zaroorat</th><th>Kya chuno</th><th>Trade-off</th></tr><tr><td>cartId se cart lena</td><td>cartId HASH</td><td>Ek item ka key lookup</td></tr><tr><td>Seller ke carts time ke order mein</td><td>sellerId + updatedAt GSI</td><td>Index eventual hai, extra write/storage ka kharcha</td></tr><tr><td>Kabhi-kabhi ke joins/reports</td><td>SQL ya S3 analytics ka raasta</td><td>Har report ko table Scan mat banao</td></tr></table>'),points:['Prefixes aur composite keys jude hue entities ki queries ko paas rakhte hain aur requests ka phailaav kam kar sakte hain. Access pattern, index aur ownership ka design dhyaan se review karo; kam tables hona har jagah ka goal nahi.','Kai tables wala design alag ownership, retention/security boundaries aur operational badlav aasaan kar sakta hai. DynamoDB transactions ek hi account/Region ki supported tables mein chal sakte hain; transaction ke liye ek hi table zaroori nahi.','Anjaane joins aur badalti queries aksar RDS/Aurora mein behtar baithti hain. Limit wale atomic key-based kaam DynamoDB mein chal sakte hain, kuch financial ledgers bhi, agar unke niyam soch kar banaye hon. "Banking matlab sirf SQL" jaisa koi pakka niyam nahi.'],code:'aws dynamodb create-table --table-name carts-v2 --attribute-definitions AttributeName=cartId,AttributeType=S --key-schema AttributeName=cartId,KeyType=HASH --billing-mode PAY_PER_REQUEST\naws dynamodb wait table-exists --table-name carts-v2\ncat backfill.json\naws dynamodb batch-write-item --request-items file://backfill.json',asli:'Kaam: terminal ek simple alag cart table aur seller ka ek saaf access pattern use karta hai. Production mein sellerId khud bhi hot ho sakta hai; bahut traffic wale seller ke liye bucketing aur merge-query ka kharcha naape hue traffic se design karo.'},
      {q:'Hot partition ko zyada kul capacity kyun theek nahi karti?',analogy:'Bazaar mein das counters khaali hain, par saare customers ek hi counter par line mein hain. Kul staff aur sabse busy counter ki capacity alag limits hain. Extra staff tabhi kaam aata hai jab requests bat sakein.',body:'<p>Har physical partition 3,000 read units/s aur 1,000 write units/s tak ke liye bana hai. 4 KB tak ke items par iska matlab 3,000 strong ya 6,000 eventual reads/s; 1 KB tak ki standard write ek write unit leti hai. Bade items aur transactional requests zyada units lete hain.</p>',points:['Requests ka barabar batna utna hi zaroori hai jitna keys ka alag hona. Adaptive capacity hot items ko alag kar sakti hai ya table/partition ki limit ke andar activity baant sakti hai; par yeh vaada nahi ki ek logical key hamesha ek hi fixed physical partition par rahegi.','On-demand mein bhi warm/scaling ke niyam, service quotas, optional maximum-throughput caps aur hot partition ki limits hain. 30 minute ke andar pichhle peak ke do guna se zyada traffic aaya toh throttle ho sakta hai; zaroorat ho toh pehle se warm karo ya dheere badhao. Provisioned auto scaling time leta hai, sale shuru hote hi turant nahi.','Write sharding control kiye suffixes se hot workload ko phailaata hai; padhne walon ko parallel queries aur merge/dedup karna pad sakta hai. Order, idempotency aur har entity ke niyam bachao; random suffix se sahi data free mein nahi milta.'],asli:'Kaam: throttling ki wajah, key level ki Contributor Insights aur consumed/provisioned metrics dekho. Planner fixture ke liye naape hue hottest-partition hisse batata hai; yeh AWS ki hash placement ka andaaza nahi lagata.'},
      {q:'Query, Scan aur read consistency mein farak kya hai?',analogy:'Query label wali drawer kholti hai; Scan almirah ki saari shelves padhta hai. Baad mein bekaar pages phenkne se shelves padhne ki mehnat wapas nahi milti.',body:wrap('<table><tr><th>Operation</th><th>Kya dena hai</th><th>Zaroori limit</th></tr><tr><td>GetItem</td><td>Poori primary key</td><td>Item na mile toh khaali object</td></tr><tr><td>Query</td><td>HASH barabar, optional RANGE condition</td><td>Padhne se pehle key se chunav; pagination</td></tr><tr><td>Scan</td><td>Table/index ko poora padhna</td><td>Filter padhne ke baad; bade scale par mehenga</td></tr></table>'),points:['Query aur Scan har page mein FilterExpression se pehle 1 MB tak padhte hain. Count 0 ho tab bhi LastEvaluatedKey se aage badho. Filter/Projection base reads ka charge kam nahi karte; query ki keys asli access pattern se match honi chahiye. Scan ka ConsistentRead poori table ka snapshot nahi banata.','Tables aur LSIs eventual ya strong reads use kar sakte hain. GSIs aur DynamoDB Streams sirf eventual reads dete hain. GSI par strong read ValidationException deta hai; yeh index ke update hone ka wait karne ka tareeka nahi.','Read size ko 4 KB units mein upar round karo; eventual reads strong ke aadhe units lete hain. Standard writes 1 KB tak round hoti hain. 5 KB item = ceil(5/4) = 2 strong read units ya 1 eventual read unit. Transactions standard strong read/write ke 2× units lete hain.'],code:`aws dynamodb query --table-name carts-v1 --key-condition-expression '#s = :s' --expression-attribute-names '{"#s":"status"}' --expression-attribute-values '{":s":{"S":"active"}}'`,asli:'Kaam: status ek reserved word hai; nakli --partition-key banane ki jagah #s alias use karo. Saare matching carts aane chahiye; Count/ScannedCount dekho aur paginate karo. Aakhri mission bySeller query karta hai aur asli rows check karta hai, command history nahi.'},
      {q:'GSI aur LSI kab chunoon?',analogy:'Kitaab ka doosra index alag tarike se dhoondhne deta hai. Naya surname index asli page number nahi badalta. Index ka update aur asli text ka update kab dikhega, iske contracts alag ho sakte hain.',body:wrap('<table><tr><th>Property</th><th>GSI</th><th>LSI</th></tr><tr><td>Key</td><td>Alag HASH, optional RANGE</td><td>Table wala hi HASH, alag RANGE</td></tr><tr><td>Banana</td><td>Table banate waqt ya baad mein</td><td>Sirf table banate waqt</td></tr><tr><td>Reads</td><td>Sirf eventual</td><td>Eventual ya strong</td></tr><tr><td>Capacity</td><td>Alag provisioned read/write capacity</td><td>Table ki capacity share karta hai</td></tr><tr><td>Quota/limit</td><td>Default 20/table, badh sakta hai</td><td>5/table; item collection ki limit 10 GB</td></tr></table>'),points:['GSI table ka billing mode leta hai. Provisioned GSI ki write capacity base table ki writes ko rok (backpressure) sakti hai. Projection ALL saare attributes rakhta hai; KEYS_ONLY/INCLUDE index ka storage aur write kharcha kam kar sakte hain, par GSI chhode gaye attributes base table se apne aap nahi laata.','Sparse index mein sirf woh items aate hain jinme index key ke attributes hain. Asli backfill mein galat type/size ki index key se index-key violations ho sakti hain; backfill par nazar rakho aur AWS diagnostics use karo. Simulator aise fixtures reject karta hai, aadhe violation repair ka model nahi banata.','Online GSI banne ke dauran base table ke reads/writes chalte rehte hain. Naye GSI ke liye TableStatus ACTIVE kaafi nahi. IndexStatus ACTIVE hone ka wait karo, phir zaroori query ke results check karo. Write ke turant baad GSI mein dikhne ki kabhi guarantee nahi; "apni write turant padhni hai" wale check ke liye base table ka strong read use karo.'],code:'aws dynamodb update-table --table-name carts-v2 --attribute-definitions AttributeName=sellerId,AttributeType=S AttributeName=updatedAt,AttributeType=N --global-secondary-index-updates file://seller-index.json\naws dynamodb wait table-exists --table-name carts-v2\naws dynamodb describe-table --table-name carts-v2\naws dynamodb query --table-name carts-v2 --index-name bySeller --key-condition-expression \'#s = :s\' --expression-attribute-names \'{"#s":"sellerId"}\' --expression-attribute-values \'{":s":{"S":"seller-1"}}\'',asli:'Kaam: cat se seller-index.json padho; bySeller mein sellerId HASH + updatedAt Number RANGE, Projection ALL hona chahiye. Simulator ready hone ke liye tay steps use karta hai, AWS ke backfill ka asli time nahi.'},
      {q:'On-demand vs provisioned ka bill kaise compare karoon?',analogy:'Meter wali taxi har trip ka charge leti hai; mahine ka bus contract reserve ki hui seats ka. Anjaane peak mein flexibility kaam ki hai; lagatar load mein reserve ka poora use maayne rakhta hai. Ek fixed price ratio har workload ko nahi samjhata.',body:'<p>Lagbhag US East Standard table ke kul list daam (2026-10-26 ko check kiye): on-demand read $0.125/million read units, write $0.625/million write units. Provisioned $0.00013/RCU-ghanta aur $0.00065/WCU-ghanta. ₹88 = $1. Inme free allowance/credits, storage, indexes, backup, replication aur transfer nahi jode.</p>',points:['Example: 5 KB item ko 1 eventual read unit aur 5 write units chahiye. Peak par 3× ke saath 300 reads/s + 150 writes/s = 900 read units/s aur 2,250 write units/s. Provisioned capacity ko peak poora karna chahiye, ya test kiya hua scaling/prewarming plan ho; sirf average wali setting throttle kar sakti hai.','Planner model: 30 din, har din 22 ghante base + 2 ghante peak. Meter wale volume ko fixed peak provisioned capacity se compare karo; 70% utilization ki headroom ka extra kharcha hai. Asli auto-scaling schedules/der, minimums aur discounts ke liye poora andaaza chahiye.','AWS ki aaj ki guidance mein on-demand default recommended throughput option hai. Naapa hua lagatar workload phir bhi provisioned ko sasta bana sakta hai; calculator chalao. "On-demand hamesha 2.5×" wala purana niyam mat maano. Standard-IA ka storage/request trade-off alag hai.'],asli:'Kaam: bataya hua minimum workload rakho: 300 reads/s, 150 writes/s, 5 KB, 3× peak. Aisa capacity mode aur distribution chuno jo peak poora kare aur model mein kul kharcha kam ho; zaroori traffic kam karke jeet nahi milegi.'},
      {q:'Retries, expiry aur recovery ke saath data sahi kaise rakhoon?',analogy:'Receipt par unique order number duplicate billing rok sakta hai; stock aur order ek sealed bundle mein saath commit ho sakte hain. Expiry ka sticker, badlav ki diary aur recovery archive: teen alag tools hain.',body:'<p>ConditionExpression write ke saath hi ek jhatke mein (atomically) check hoti hai. attribute_not_exists(cartId) us request mein overwrite ko reject karta hai. Optimistic locking version compare karke agla version likhta hai. Har writer ko sahi condition chahiye; ek conditional request se koi hamesha ka niyam nahi lag jaata.</p>',points:['TransactWriteItems: 100 tak alag items aur 4 MB, same account/Region; saare supported actions ya toh commit hote hain ya koi nahi. Do actions ek hi item par nahi ho sakte. BatchWriteItem: 25 puts/deletes, 16 MB request, batch atomic nahi, har item par condition nahi; UnprocessedItems ko backoff ke saath retry karo. Transaction ka ClientRequestToken 10 minute tak idempotent hai, hamesha ke liye nahi.','TTL ko Number epoch seconds chahiye. Expire hue items kai din tak reh sakte hain; app ke reads ko expiry khud check karni chahiye. Streams har item ke badlav ka record 24 ghante tak rakhta hai, har item ke order mein; consumer ko duplicate processing ke liye phir bhi idempotency chahiye. Streams hamesha ka backup nahi.','PITR ki window 1–35 din set ho sakti hai; latest restore ho sakne wala time aam taur par abhi se lagbhag 5 minute peeche hota hai, aur restore nayi table mein hota hai. Window chhoti karne se PITR ka daam kam nahi hota. S3 export ke liye PITR chahiye, table RCUs nahi lagte, aur analytics ke liye theek hai; export app ka query index nahi.'],code:"aws dynamodb update-continuous-backups --table-name carts-v2 --point-in-time-recovery-specification PointInTimeRecoveryEnabled=true,RecoveryPeriodInDays=35\naws dynamodb update-time-to-live --table-name carts-v2 --time-to-live-specification Enabled=true,AttributeName=expiresAt\naws dynamodb describe-time-to-live --table-name carts-v2\naws dynamodb put-item --table-name carts-v2 --item file://new-cart.json --condition-expression 'attribute_not_exists(cartId)'",asli:'Kaam: terminal sahi create ke baad jaan-boojh kar duplicate-cart.json try karta hai; ConditionalCheckFailedException aana chahiye aur total 499 bacha rehna chahiye. Interview mein fail hua atomic checkout aur phir safal stock/order commit test hota hai.'},
      {q:'Global Tables, SQL aur cache ka aakhri faisla kya hai?',analogy:'Kai shehron mein branch ka khata rakhne se business ke takraav apne aap nahi sulajhte. Replica ka consistency contract aur kaun likhega, yeh pehle chuno; sirf branches ki ginti safety prove nahi karti.',body:wrap('<table><tr><th>Zaroorat</th><th>Kya chuno</th><th>Review</th></tr><tr><td>Pata hua key-based pakka access</td><td>DynamoDB</td><td>Keys, units, niyam, indexes</td></tr><tr><td>Interactive joins aur badalti SQL</td><td>RDS/Aurora</td><td>Schema, connections, read/HA design</td></tr><tr><td>Badi files/analytics exports</td><td>S3 + sahi query service</td><td>Item mein pointer/hash rakho</td></tr><tr><td>Sorted-set leaderboard</td><td>Valkey/Redis-compatible cache</td><td>Durability/rebuild aur freshness</td></tr><tr><td>DynamoDB ke eventual reads tez karna</td><td>DAX</td><td>Supported APIs, purane reads, extra kharcha</td></tr></table>'),points:['Global Tables ka default MREC asynchronous replication aur har item par "aakhri likhne wala jeete" (last-writer-wins) use karta hai. Local strong read door ki sabse nayi write ki guarantee nahi deta. Transactions sirf chalane wale Region mein atomic hain; door ke replicas thodi der transaction ka aadha asar dikha sakte hain.','MRSC Regions ke beech strong consistency deta hai, aaj ki teen-Region topology ke saath: 3 replicas ya 2 replicas + witness. Mode banne ke baad nahi badalta. Aaj ke eligible Regions continents ke paar bhi chune ja sakte hain; Region support check karo. MRSC mein TTL, LSI ya transactions nahi; GSIs eventual hi rehte hain.','Galti jo sab karte hain: PK ko wahin badalna; FilterExpression ko sasta index samajhna; on-demand ko "kabhi throttle nahi" maanna; TTL ko payment ki deadline banana; replica ya index se global uniqueness ki ummeed rakhna.','Production mein aisa hota hai: ek bada seller GSI ko hot kar deta hai, backfill writes se takraata hai, TTL se delete hue records replay mein confusion laate hain, retries data overwrite kar dete hain, aur cutover ke waqt ek saath hue updates kho jaate hain. Interview ke sawaal: hot cart vs hot seller? Deletes kaise milaoge? Kis read ko strong consistency chahiye? Rollback ready hai, iska saboot kya?'],asli:'Faisla kaise karein: file 400 KB se badi → S3 pointer; anjaane joins → SQL; fixed key queries → niyam ke saath DynamoDB; sirf tezi/ranking → review kiya cache. Kai Regions chahiye → consistency, Region, latency aur features dekh kar MREC/MRSC chuno.'}
    ],
    myth:[
      {myth:'“UpdateTable se partition key badal denge.”',sach:'Primary key badal nahi sakti. Alag table, check kiya backfill aur control kiya cutover, ya soch kar banayi write-sharding migration chahiye.'},
      {myth:'“On-demand matlab na hot partitions, na quotas.”',sach:'Hot partition ki capacity, scaling/warm limits, optional caps aur service quotas rehte hain. Traffic bata na ho, toh sirf alag keys kaafi nahi.'},
      {myth:'“FilterExpression reads kam karti hai; GSI strong read sabse naya data dega.”',sach:'Filters padhne ke baad lagte hain aur capacity wapas nahi dete. GSI sirf eventual hai; sahi key/index aur zaroorat par base table ka strong read use karo.'},
      {myth:'“DynamoDB mein kaam ke transactions nahi; TTL exact time par delete karta hai.”',sach:'Transactions supported scope mein 100 alag items/4 MB tak chalte hain. TTL ka background delete kai din late ho sakta hai; app mein expiry check phir bhi zaroori.'}
    ],
    playbook:{title:'Pehle access pattern: kab DynamoDB, kab doosra option',use:['Pakka key-value/document access, jahan queries pata hon aur traffic naapa gaya ho','Conditional writes/optimistic locking, ya limit wale atomic key kaam','Global replicas tabhi jab consistency/feature/Region ka contract chun liya ho'],avoid:['Serving table par anjaane joins ya kabhi-kabhi ki reports','400 KB ke items ke andar badi binary files','TTL/MREC se exact time par expiry ya global unique business niyam maan lena'],how:['Access patterns aur sahi data ke niyam likho','Poori primary key aur sparse/projected indexes chuno; sabse hot item/seller test karo','Round kiye units, peak aur poora kharcha nikaalo','Data milate hue migrate karo, catch-up, control kiya cutover aur rollback; asli data check karo'],redflags:['In-place key rewrite','Kul capacity bahut bachi, par ek key par jama throttles','GSI bana par ACTIVE nahi; base write ko turant index mein dikhna maan liya','Batch ko atomic maana, ya token ko hamesha ki idempotency'],rule:'Access pattern → key ka batna → consistency/niyam → peak/kharcha → migration aur recovery ka saboot.'},
    exam:[
      {cue:'"known key access, managed high scale"',pick:'DynamoDB candidate',why:'Item size, hot keys, consistency aur limit wale niyam check karo; bina limit ke scale ki guarantee nahi.'},
      {cue:'"eventual DynamoDB microsecond read acceleration"',pick:'DAX',why:'Cache/read APIs aur freshness fit hain; strong reads seedhe DynamoDB tak jaate hain.'},
      {cue:'"multi-Region active writes"',pick:'Global Tables',why:'MREC/MRSC saaf chuno; takraav, Regions aur features ki limits alag hain.'},
      {cue:'"expire sessions"',pick:'TTL + app mein expiry check',why:'Number epoch seconds; delete kai din late ho sakta hai.'},
      {cue:'"react to item changes"',pick:'Review kiye consumer ke saath Streams',why:'24 ghante ka change log, har item ka order; consumer ko retries phir bhi sambhalne hain.'},
      {cue:'"unknown new traffic / measured steady load"',pick:'On-demand / compare provisioned',why:'Units ke aaj ke daam aur peak/scaling ki zaroorat dekho, fixed price ratio nahi.'},
      {cue:'"recover accidental write in configured last 1–35 days"',pick:'PITR se nayi table mein restore',why:'Asli earliest/latest restore times check karo; on karna recovery drill nahi hai.'},
      {cue:'"query by another attribute"',pick:'GSI; LSI tabhi jab HASH same ho aur table banate waqt ka design fit ho',why:'GSI eventual hai aur iska kharcha alag; hot index keys writes ko rok sakti hain.'},
      {cue:'"all-or-nothing stock plus order"',pick:'TransactWriteItems',why:'Ek account/Region mein 100 alag items/4 MB; batch writes mein transaction wala atomic nahi hota.'}
    ],
    stages:[
      {type:'dryrun',title:'🔬 Active cart se seller index tak',goal:'Har "Agla" click par kaun kya kar raha hai aur state dekho; teen faislon mein access pattern aur consistency chuno.',nodes:[N('user',150,255,{label:'Cart API'}),N('dynamodb#old',500,120,{label:'status HASH'}),N('dynamodb#new',500,390,{label:'cartId HASH'}),N('dynamodb#index',850,255,{label:'bySeller GSI'})],edges:[{from:'user',to:'dynamodb#old'},{from:'user',to:'dynamodb#new'},{from:'dynamodb#new',to:'dynamodb#index'}],panels:[{id:'data',title:'Item / capacity'},{id:'proof',title:'Correctness / visibility'}],steps:[
        {say:'ShopKaro par sale ki cart writes aati hain. Purani key status + cartId use karti hai; lab ke 1000 mein se 950 carts ka status active hai. Rows ki ginti jhukaav (skew) dikhati hai, asli throttling nahi.',nodes:{'dynamodb#old':{tone:'busy',badge:'active traffic'}},flows:[{from:'user',to:'dynamodb#old',label:'hot key',tone:'slow'}],panels:{data:['Fixture ka data: hot physical partition >1000 write units/s','Baaki physical partitions/table mein capacity bachi hai'],proof:['Source carts retained','Logical key ka group hamesha ki physical jagah nahi hai']}},
        {say:'Contributor Insights aur throttle ki wajah se pata chalta hai ki load ek jagah jama hai. Sirf kul capacity badhane se naapi gayi hot partition ko rahat ki guarantee nahi.',ask:Q('Naapi gayi, ek partition par jama writes ka sabse achha jawaab?','Traffic dekh kar keys/shards dobara design karo aur business ke niyam bachao',['Jama hue access path ko dekhe bina kul capacity badha do','Hot partition aur warm limits check kiye bina billing mode badal do','Write ka batna ya retry ka asar dekhe bina timeout kam kar do'],1,'Key ka sahi batna jama hone ki dikkat theek karta hai. Extra kul capacity ya on-demand ke baad bhi hot partition ki limit reh sakti hai; timeout na batna badalta hai, na data sahi karta hai.')},
        {say:'Ravi cartId key wali alag table banata hai. Is fixture mein writers ruke hue hain. Backfill saare attributes copy karta hai aur manzoori se pehle asli rows compare karta hai.',flows:[{from:'user',to:'dynamodb#new',label:'cart IDs',tone:'ok'}],nodes:{'dynamodb#old':{tone:'idle',badge:'preserved'},'dynamodb#new':{tone:'new',badge:'verified rows'}},panels:{data:['cart-101,102,103 preserved','Production mein chalti writes ke liye catch-up/milaan chahiye'],proof:['Primary key wahin nahi badal sakti','Review kiye rollback ke liye purani table bachi']}},
        {say:'Seller ki list ke liye ek aur access pattern chahiye. bySeller sellerId HASH + updatedAt RANGE use karta hai. Query se pehle asli backfill poora hona chahiye; sirf table ACTIVE kaafi nahi.',flows:[{from:'dynamodb#new',to:'dynamodb#index',label:'eventual',tone:'slow'}],nodes:{'dynamodb#index':{tone:'busy',badge:'CREATING → ACTIVE'}},ask:Q('Base table ki write abhi safal hui. Kya seller GSI mein sabse naya data pakka hai?', 'Nahi; GSI eventual hai, zaroori confirmation ke liye base ka strong read use karo',['Haan; table ACTIVE hone se har GSI read globally strongly consistent ho jaata hai','Haan; GSI par ConsistentRead data lautane se pehle propagation zabardasti karwata hai','Nahi; GSI index banne ke baad likhe gaye badlav kabhi dikha hi nahi sakta'],2,'GSI eventual hai. Table ready hone se index ke update hone ka vaada nahi; GSI par ConsistentRead reject hota hai; active GSI baad ki writes bhi leta hai.')},
        {say:'Cart create attribute_not_exists(cartId) use karta hai. Total 0 wali duplicate request ek jhatke mein fail hoti hai aur total 499 bacha rehta hai. Condition sirf is request par hai, har aage ke writer par nahi.',panels:{proof:['Pehla conditional create safal','Duplicate receives ConditionalCheckFailedException','Readback mein total 499, koi duplicate item nahi']},ask:Q('Ek safal conditional create kya pakka karta hai?','Woh request atomic thi; har doosre writer ko apni condition phir bhi chahiye',['Ab table aage ki har PutItem call par yeh business niyam laagu karti hai','Business ki pehchaan ke bina bhi har retry hamesha ke liye dedup ho jaata hai','BatchWriteItem ka duplicate pichhle PutItem ki condition apne aap le lega'],0,'Condition us ek write ki hai. Koi hamesha ka niyam nahi lagta; idempotency ke liye pakki pehchaan aur har zaroori write path chahiye; batch conditions nahi lete.')},
        {say:'Ready/config checks ke baad aakhri seller-1 query teen sahi carts lautati hai. Moto aur simulator asli latency, TTL ka purana hona, live cutover ya replicas ka milna prove nahi karte.',nodes:{'dynamodb#new':{tone:'ok',badge:'data verified'},'dynamodb#index':{tone:'ok',badge:'3 seller carts'}},panels:{data:['cart-101 + cart-103 + cart-104','Source rows unchanged'],proof:['PITR 35 aur TTL ka metadata on','Asli physical throughput ka daava nahi']}}
      ],lesson:'Access pattern → na badalne wali key ki migration → index ka ready hona → request ki condition → asli data ka saboot.'},
      {type:'flowlab',title:'🎛️ Round kiye units, peak aur kam kul bill',scenario:'Fixture ko kam se kam 300 eventual reads/s, 150 standard writes/s, 5 KB items aur 3× peak chahiye. Har din 22 ghante base + 2 ghante peak. Naapa hua sabse hot partition ka hissa: ek jagah jama 100% ya bata hua 10%. On-demand ke warm/table quotas taiyaar maane gaye; asli throughput ka simulation nahi.',goal:'Zaroori workload bachao. Aisa distribution, mode aur capacity plan chuno jo peak poora kare aur model mein sasta ho. Try karo: 300 reads/s, 150 writes/s, 5 KB, 3×, provisioned, peak capacity aur bata hua traffic.',knobs:[
        {id:'reads',label:'Base eventual reads',min:100,max:300,step:100,value:300,fmt:v=>v+' /s'},
        {id:'writes',label:'Base standard writes',min:50,max:150,step:50,value:150,fmt:v=>v+' /s'},
        {id:'kb',label:'Stored item size',min:1,max:9,step:4,value:5,unit:'KB'},
        {id:'peak',label:'Two-hour daily peak',min:1,max:5,step:2,value:3,unit:'×'},
        {id:'mode',label:'Billing mode',min:0,max:1,step:1,value:1,labels:{0:'On-demand',1:'Provisioned'}},
        {id:'capacity',label:'Provisioned plan',min:0,max:2,step:1,value:0,labels:{0:'Base only',1:'Peak fixed',2:'Peak at70% utilization'}},
        {id:'key',label:'Hot partition share',min:0,max:1,step:1,value:0,labels:{0:'100% hottest',1:'10% hottest'}}
      ],model:k=>{const p=plan(k);return {readouts:[{label:'Peak required units',value:p.peakR+' read/s · '+p.peakW+' write/s',tone:'acc'},{label:'Provisioned chosen',value:p.rcu+' RCU · '+p.wcu+' WCU',tone:p.capacityOK?'ok':'bad'},{label:'On-demand gross/month',value:'approx $'+p.ondemand.toFixed(2),tone:'acc'},{label:'Provisioned gross/month',value:'approx $'+p.provisioned.toFixed(2),tone:'acc'},{label:'Chosen / required minimum',value:'approx ₹'+Math.round(p.cost*88)+' · '+(p.valid?'workload retained':'below required load'),tone:p.valid?'ok':'bad'},{label:'Hottest physical partition',value:p.hot?'bataye unit limit se zyada':'bataye unit limit ke andar',tone:p.hot?'bad':'ok'}],verdict:{ok:p.ok,text:p.ok?'Peak capacity/distribution fit aur kam kul kharcha chuna gaya. Production se pehle asli warm limits, scaling, headroom aur chhode gaye saare kharche check karo.':!p.valid?'Zaroori traffic/item/peak kam karke jeet nahi milegi.':p.hot?'Naapi hot partition limit se zyada hai; sirf kul billing/capacity badalna kaafi nahi.':!p.capacityOK?'Sirf base wala provisioned plan peak poora nahi kar sakta. Auto scaling turant nahi hota.':'Is workload par fixed peak provisioned vs meter wala on-demand compare karo; headroom ka kharcha zyada hai.'}};},check:k=>plan(k).ok,lesson:'Read: eventual ke liye ceil(KB/4) × 0.5; write: ceil(KB/1). Daam: US East Standard lagbhag $0.125/M read, $0.625/M write, $0.00013/RCU-h, $0.00065/WCU-h; 30 din/720 ghante, ₹88/$. Kul kharche mein free allowances, credits, storage/indexes, backups, replication, network aur tax nahi. Capacity ka chunav model hai, load test nahi.'},
      {type:'bins',title:'🗂️ Zaroorat ke liye sahi store',instructions:'Pata access pattern, file ka size aur query ka shape dekh kar chuno. Ranking/cache ke chunav mein rebuild aur durability ka alag review hai.',bins:[{id:'ddb',label:'DynamoDB'},{id:'sql',label:'RDS / Aurora'},{id:'s3',label:'S3'},{id:'cache',label:'Valkey / Redis-compatible cache'}],items:[
        {text:'ID se pakka cart lena, seller ka pata access pattern',bin:'ddb',explain:'Pata key/index access, saaf conditions aur traffic ke batne ke saath.'},{text:'Orders, customers aur payments ke beech badalte interactive joins',bin:'sql',explain:'Relational queries theek baithti hain; sirf transactions DynamoDB ko bahar nahi karte.'},{text:'20 MB product photo, cart item mein checksum/pointer ke saath',bin:'s3',explain:'File 400 KB se badi; serving database mein sirf metadata pointer rakho.'},{text:'Top 100 players ka rank, sorted-set updates, review kiya rebuild raasta',bin:'cache',explain:'Sorted sets ranking ke liye theek; ek game_id wala DynamoDB partition + DAX har jagah ka ilaaj nahi.'},{text:'Do pata keys par stock ko atomic ghatana + order put',bin:'ddb',explain:'Limit wala TransactWriteItems theek hai, agar saare niyam aur supported scope poore hon.'},{text:'Analytics ke liye har mahine purane Parquet exports',bin:'s3',explain:'Sahi query service ke saath object analytics serving table ke scans se bachata hai.'}
      ]},
      {type:'fill',title:'🧩 Reserved word status wali Query: asli CLI',instructions:'Chaar khaali jagah bharo. status ka alias lagao, typed values do, aur pehle se bani composite-key source ko query karo. Koi nakli --partition-key flag nahi.',template:`aws dynamodb {0} --table-name carts-v1 \\\n  --{1} '#s = :s' \\\n  --expression-attribute-names '{"#s":"{2}"}' \\\n  --expression-attribute-values '{":s":{"{3}":"active"}}'`,tokens:['query','key-condition-expression','status','S','scan','partition-key','sellerId','N'],blanks:[{answer:'query',explain:'Pata HASH barabar ho toh Query; Scan poore pages padhta hai.'},{answer:'key-condition-expression',explain:'Asli CLI is flag se HASH ka barabar hona batata hai.'},{answer:'status',explain:'#s reserved attribute naam status ko resolve karta hai; #s naam ka koi field save nahi hota.'},{answer:'S',explain:'Source ka status String hai; Number key type se match nahi karega.'}]},
      {type:'triage',title:'🩺 Table mein capacity bachi, par ek access path hot',symptom:'Sale ke data mein ProvisionedThroughputExceededException aa raha hai. Fixture hot partition ke throttle ki asli wajah deta hai; aankh band karke capacity khareedne se pehle schema aur access ki frequency review karo.',goal:'Clue commands chalao, phir asli wajah aur repair chuno.',commands:[
        {cmd:'aws dynamodb describe-table --table-name carts-v1',out:'{"KeySchema":[{"AttributeName":"status","KeyType":"HASH"},{"AttributeName":"cartId","KeyType":"RANGE"}],"TableStatus":"ACTIVE"}',clue:true,note:'Zyaadatar active requests status ka ek item collection share karti hain; physical jagah ke liye telemetry phir bhi chahiye.'},
        {cmd:'aws dynamodb describe-contributor-insights --table-name carts-v1',out:'{"ContributorInsightsStatus":"ENABLED","ContributorInsightsRuleList":["DynamoDBContributorInsights-PKC-carts-v1-fixture"]}\nDashboard fixture: active key accounts for95% of cart writes',clue:true,note:'Kaun sa contributor zyada hai, yeh alag saboot hai; sirf API status har key ki frequency nahi lautata.'},
        {cmd:'aws logs tail /shopkaro/cart-api',out:'ProvisionedThroughputExceededException ThrottlingReason=TableWriteKeyRangeThroughputExceeded; aggregateConsumed=4200/10000WCU; hottestPhysicalPartition=1350writeUnits/s',clue:true,note:'Kul capacity bachi hone par bhi naapi partition ki limit paar hui; yeh course ka synthetic log hai, Moto ka output nahi.'},
        {cmd:'aws dynamodb describe-continuous-backups --table-name carts-v1',out:'{"PointInTimeRecoveryStatus":"ENABLED"}',clue:false,note:'Recovery config hot partition ke write pressure ko nahi hataata.'}
      ],questions:[
        Q('"Kul capacity bachi, phir bhi throttle" ki ulti baat ko kaunsa saboot samjhata hai?','Jama hui writes mein ek naapi hot physical partition apni limit paar kar rahi hai',['PITR bahut saare backups rakhta hai aur har second table ki saari write capacity kha jaata hai','Optional sort key DynamoDB par har composite-key PutItem ko galat bana deti hai','GSI ka strong read har base-table write burst ke liye kaafi capacity ki guarantee deta hai'],3,'Hot partition vs kul capacity hi dikhi wajah/metrics samjhati hai. PITR recovery ke liye hai, composite keys sahi hain, aur GSI na strong read deta hai na base writes ki capacity.'),
        Q('Kaunsa repair data sahi rakhte hue load ka jama hona theek karta hai?','Behtar key wali table banao, data milao aur review kiya cutover/rollback karo',['UpdateTable pehli HASH key badal deta hai, table ka data layout waisa hi rakh kar','Active carts delete karo, taaki table ke metrics jama requests dikhana band kar dein','Timeout badhao aur maan lo ki retries pehle se bane kisi cart ko overwrite nahi kar sakte'],0,'Naya key design + safe migration load ke batne ko theek karta hai. Primary key wahin nahi badalti; delete karne se carts kho jaate hain; bina condition ke timeout/retries na access path theek karte hain na niyam.')
      ]},
      {type:'terminal',title:'🖥️ Carts migrate karo; index aur duplicate se bachav check karo',instructions:'Writers ruke hue hain. ls/cat se chaar files dekho. Numbered hisse follow karo; output mein index ka status aur reject hua duplicate check karo.',goal:'<p><b>1 — Banao/backfill:</b> carts-v2 mein cartId String HASH, PAY_PER_REQUEST; ACTIVE hone ka wait; backfill.json ka batch-write. Source carts-v1 ko mat chhuo.</p><p><b>2 — Seller lookup:</b> sellerId String + updatedAt Number definitions ke saath seller-index.json jodo. Table ka wait karo, phir describe-table: bySeller ACTIVE hona chahiye. Simulator ke tay steps ready hona dikhate hain; asli backfill ka time alag hota hai.</p><p><b>3 — Safety:</b> PITR 35 din; TTL expiresAt on + describe-time-to-live. new-cart.json ka conditional create; duplicate-cart.json ka conditional retry fail hona chahiye aur total 499 bacha rehna chahiye.</p><p><b>4 — Saboot:</b> #s alias ke saath bySeller seller-1 query karo. cart-101, 103, 104 saare sahi attributes ke saath aane chahiye. Sirf yahi aakhri current data result mission poora karta hai.</p>',account:seed(),files:FILES,tasks:TASKS,solution:SOLUTION,solutionErrors:{10:'ConditionalCheckFailedException'},hints:['Alag table use karo; primary key dobara nahi likhi ja sakti. Copy karne se pehle ls aur cat backfill.json dekho.',SOLUTION.slice(0,3).join(' phir '),SOLUTION.slice(3,6).join(' phir '),SOLUTION.slice(6,9).join(' phir '),SOLUTION.slice(9).join(' phir ')],success:AG.allOf(TASKS),successText:'Teeno asli carts aur saare attributes bache. Alag v2 mein sahi key/GSI/PITR/TTL hain, total 0 wala duplicate reject hua, aur current seller query teen sahi carts lautati hai. Live cutover, asli throughput, TTL ka purana hona ya PITR restore prove nahi hua.'},
      {type:'docker',title:'🐳 Lab15: 1,000 asli local carts',project:'15-dynamodb-access-patterns',goal:'Local Moto par asli CLI/SDK requests chalao aur poore item ki barabari, conditional reject aur atomic rollback dekho. Is lab ke liye Docker nahi chahiye.',why:'App ka engine limit mein hai. Local API execution syntax, typed data aur emulator ki kamiyan mission ke checks se alag pakadta hai.',steps:[
        {text:'Local environment source karo; lab.py padho; is run ki alag v1 table banao.',cmd:'source ../env.sh && ../.venv/bin/python -I lab.py setup',expect:'SOURCE items 1000; logical key ki ginti active 950/saved 50. Bane naam har baar alag hote hain.'},
        {text:'Migrate karo aur GSI/PITR/TTL, duplicate aur checkout exercises chalao.',cmd:'../.venv/bin/python -I lab.py exercises',expect:'BACKFILL equalAttributes true; seller count 100→101; duplicate reject hua aur total 499. ROLLBACK mein stock 1/order nahi; ATOMIC-COMMIT mein stock 0/order quantity 1.'},
        {text:'Sirf ledger ki apni tables delete karo aur check karo ki woh hat gayi.',cmd:'../.venv/bin/python -I lab.py cleanup',expect:'OWNED_TABLES_REMAIN []'}
      ],observe:Q('Local lab kya pakka karti hai?', 'Asli data migration aur requests ka sahi hona, Moto runtime ki saaf limits ke saath',['AWS ka naapa physical throughput aur har key ki pakki partition jagah','Exact time par TTL delete aur 35 din ki check ki hui point-in-time recovery','Regions ke beech strong consistency aur bina data khoye production app ka cutover'],1,'Asli requests aur items ki barabari saboot hain. Moto physical throughput, TTL/PITR ka beeta time, global replication ya live cutover prove nahi karta. Same token se transaction replay Moto ki ek dikhi hui kami hai.')},
      {type:'quiz',title:'🎓 Access pattern aur sahi data ke faisle',questions:[
        Q('Table status HASH aur cartId RANGE use karti hai. Ab cartId HASH chahiye. Safe tareeka?', 'Alag table banao, backfill aur live badlav milao, phir rollback ke saath cutover karo',['UpdateTable seedha HASH badalta hai aur har purane item ko apne aap rehash kar deta hai','Items ke andar status ka naam badlo aur maan lo ki DynamoDB table ka KeySchema bhi badal dega','Naye schema ko test karne se pehle source items delete karo, taaki writers ko duplicates na milein'],2,'Primary key ka schema badal nahi sakta. Nayi table aur migration/catch-up use karo. Item ke fields ka naam badalne se schema nahi badalta; manzoori se pehle source delete karna recovery khatam kar deta hai.'),
        Q('Ek 5 KB item eventual read hota hai aur bina transaction ek baar likha jaata hai. Har operation ke units?', 'Size round karne ke baad ek eventual read unit aur paanch standard write units',['Aadha eventual read unit aur ek write unit, kyunki ek request ek API call hai','Do eventual read units aur das write units, kyunki har operation transactional hai','Paanch eventual read units aur paanch write units, kyunki dono 1 KB par round hote hain'],3,'ceil(5/4) × 0.5 = 1 eventual read unit; ceil(5/1) = 5 write units. Sirf request ki ginti size ko bhool jaati hai; 2× transactions par lagta hai; read 4 KB par round hota hai, 1 KB par nahi.'),
        Q('Query 1 MB padhti hai, phir filter 99% items phenk deta hai. Kaunsi baat sahi hai?', 'Filter lautayi rows kam karta hai, par padhe gaye data ki capacity phir bhi lagti hai',['Filter asli reads se pehle chalta hai, isliye phenke gaye 99% par read capacity nahi lagti','ProjectionExpression output se chhode har attribute ke read units wapas kar deta hai','Filter ke baad khaali page prove karta hai ki baaki kisi query page mein matching item nahi'],0,'Filters/projections padhi gayi capacity wapas nahi dete. Count 0 ho tab bhi LastEvaluatedKey se aage badho. Key ka chunav/index behtar karo; output ka size read billing ka meter nahi.'),
        Q('Write ka acknowledgement aate hi seller GSI ko order dikhana hai. Sahi contract?', 'Zaroori confirmation ke liye base table ka strong read use karo; GSI mein dikhna eventual hai',['GSI par ConsistentRead true karo, taaki woh writer ke saath turant sync ho jaaye','Ek baar table-exists ka wait karo aur maan lo ki aage ki har index write turant dikhegi','Same HASH wala GSI use karo, kyunki matching partition keys apne aap strong reads de deti hain'],1,'GSI eventual hi hai, key milti-julti ho tab bhi. Strong reads base tables/LSIs par milte hain; GSI ka ConsistentRead reject hota hai. Table ka shuru mein ready hona baad ki der nahi hataata.'),
        Q('Kuch puts safal hone ke baad BatchWriteItem UnprocessedItems lautata hai. Sahi tareeka?', 'Sirf bachi requests ko backoff ke saath retry karo; batch atomic transaction nahi hai',['Kuch retry mat karo, kyunki UnprocessedItems aane par pehle ke saare puts rollback ho jaate hain','Har PutRequest ko conditional create maano, kyunki BatchWriteItem overwrites rokta hai','Poora batch ek saath sau actions mein bhejo, kyunki BatchWriteItem 100 items allow karta hai'],2,'Batch writes atomic nahi; kuch puts/deletes safal ho sakte hain aur baaki ko retry chahiye. Batch mein max 25 actions aur koi condition nahi; 100 transaction ki limit hai. Bina condition ke puts overwrite kar sakte hain.'),
        Q('Sessions ka number wala expiresAt beet chuka hai, phir bhi woh dikh rahe hain. App ko kya karna chahiye?', 'Padhte waqt expiry khud check karo aur TTL ko eligible items baad mein hataane do',['Maan lo TTL toota hai, kyunki har eligible item expiresAt par bilkul usi time gayab hona chahiye','Expiry ko formatted String mein rakho, taaki delete karne wala worker exact time tay kar sake','TTL band karo aur maan lo ki Global Table ka replica expire sessions ko hamesha chhaant dega'],3,'TTL ka delete kai din late ho sakta hai. App mein expiry check zaroori; attribute Number epoch seconds hona chahiye. String dates aur replicas deadline laagu nahi karte.'),
        Q('Do pata items par stock ka atomic ghatna aur order banana chahiye. Sabse sahi baat?', 'Conditional transaction lagao; supported actions ya saare commit honge ya saare rollback',['Do alag PutItem calls karo, kyunki response ka order atomic commit pakka karta hai','BatchWriteItem use karo, kyunki har multi-item batch wahi atomic isolation deta hai','Zyada safety ke liye dono operations ek hi transaction mein same stock key par daalo'],0,'TransactWriteItems ek account/Region mein 100 alag items/4 MB support karta hai. Alag calls aur batches mein "sab ya kuch nahi" nahi hota; kai actions ek hi item par nahi ho sakte.'),
        Q('MREC vs MRSC Global Tables: aaj ki sahi baat kaunsi hai?', 'MREC async hai; MRSC ke strong replicas teen-Region topology aur feature limits ke saath',['Dono modes Regions ke beech atomic transactions dete hain aur har replica par TTL support karte hain','MREC par local strong reads hamesha kisi bhi door ke Region ki sabse nayi write dikhate hain','Pehle se bani MREC table ko MRSC mein badalna bina migration har feature bachata hai'],1,'MREC replication async hai, aur transaction sirf local Region mein atomic. MRSC ka mode banne ke baad nahi badalta, aur abhi TTL/LSI/transactions nahi; GSI eventual rehta hai. Eligible Regions aur topology review karo.')
      ]},
    ],
    interview:{title:'Interview: niyam, hot keys aur atomic checkout',instructions:'Chaar trade-off sawaalon ke baad stock 1 wale fixture mein fail aur safal transaction ki asli state prove karo.',questions:[
      Q('10 lakh carts ke alag IDs hain, par ek seller zyaadatar writes karta hai. Kya review karna hai?', 'Sabse hot item/index keys dekho, aur shard tabhi karo jab read/niyam ki strategy tay ho',['Table ko safe bol do, kyunki alag primary keys activity ka barabar batna pakka karti hain','Seller par load naape bina sellerId GSI jodo, kyunki index writes free hain','DAX on karo aur maan lo ki read caching se base table ka har write throttle gayab ho jaayega'],2,'Zyada alag keys ka matlab barabar traffic nahi; seller GSI hot ho sakta hai. Sharding ke liye fan-out/niyam ka design chahiye. GSI writes capacity leti hain; DAX ka read cache saari writes nahi baant-ta.'),
      Q('Kya payment jaisa ledger kabhi DynamoDB par theek ho sakta hai?', 'Haan, limit wale key patterns par, saaf atomic niyam aur audit kiye design ke saath',['Nahi, kyunki DynamoDB kisi bhi config mein atomic multi-item transaction support nahi karta','Haan, kyunki MREC replication har cross-Region transaction ko globally atomic bana deti hai','Haan, kyunki BatchWriteItem request har stock aur ledger badlav ka commit pakka karti hai'],3,'Limit wale transactional key workloads fit ho sakte hain. DynamoDB transactions support karta hai; MREC mein door ki atomicity nahi; BatchWriteItem mein transaction ki guarantee nahi. Financial sahi-galat ke liye phir bhi poora design chahiye.'),
      Q('Ek asli migration Scan ConsistentRead use karta hai, jabki writers chal rahe hain. Kya missing hai?', 'Change capture aur milaan (deletes ke saath), catch-up aur control kiya cutover/rollback',['Aur kuch nahi, kyunki strong Scan poori table ka ek snapshot lautata hai','Sirf table ka naam badlo, kyunki UpdateTable primary keys aur naam ek jhatke mein badal deta hai','Sirf TTL, kyunki poore backfill ke dauran expire hui source rows badal nahi sakti'],0,'Strong Scan poori table ka snapshot nahi. Live migration mein ek saath hue badlav sambhalne aur manzoori/rollback chahiye; table ki key/naam dobara likhna mumkin nahi; TTL async hai, migration ka taala nahi.'),
      Q('Checkout retry wahi ClientRequestToken dobara use karta hai. Kaunsa contract samjhaoge?', 'AWS 10 minute ke andar dedup karta hai; token ki window ke baad bhi business idempotency rakho',['Token ek hamesha ka unique order niyam laga deta hai, retention window ke baad bhi','Token ke liye har retry par request payload badalna padta hai, taaki failures alag pehchaane jaayein','Moto ka replay behaviour prove karta hai ki deployed AWS token wale transaction retries support hi nahi karta'],1,'Wahi token dobara bhejna 10 minute ke andar idempotent hai; parameters badle toh takraav hota hai. Token hamesha ka business niyam nahi; Moto mein dikhi replay ki kami AWS ka matlab nahi badalti.'),
      {terminal:(()=>{const transaction=n=>[{Update:{TableName:'checkout',Key:{id:{S:'SKU#kurta'}},UpdateExpression:'SET available = available - :n',ConditionExpression:'available >= :n',ExpressionAttributeValues:{':n':{N:String(n)}}}},{Put:{TableName:'checkout',Item:{id:{S:'ORDER#9001'},quantity:{N:String(n)}},ConditionExpression:'attribute_not_exists(id)'}}];
        const initial=[{id:'SKU#kurta',available:1}],solution=['aws dynamodb transact-write-items --transact-items file://too-many.json --client-request-token checkout-failed','aws dynamodb transact-write-items --transact-items file://checkout.json --client-request-token checkout-success',`aws dynamodb get-item --table-name checkout --key '{"id":{"S":"ORDER#9001"}}' --consistent-read`];
        const tasks=[{text:'Quantity 2 wala reject hua transaction: stock 1 bacha aur order nahi bana',check:s=>{const r=s.ddbLastFailedTransaction,t=r?.tables?.find(t=>t.name==='checkout');return !!r&&r.reasons[0]==='ConditionalCheckFailed'&&r.items?.length===2&&r.items[0].Update?.Key?.id?.S==='SKU#kurta'&&r.items[0].Update.ExpressionAttributeValues?.[':n']?.N==='2'&&r.items[1].Put?.Item?.id?.S==='ORDER#9001'&&r.items[1].Put.Item.quantity?.N==='2'&&equalRows(t?.items,initial);}}, {text:'Atomic quantity 1 commit: stock 0 + ek order quantity 1, aur koi rows nahi',check:s=>{const r=s.ddbLastTransaction,t=r?.tables?.find(t=>t.name==='checkout'),expected=[{id:'SKU#kurta',available:0},{id:'ORDER#9001',quantity:1}];return !!r&&r.items?.length===2&&r.items[0].Update?.Key?.id?.S==='SKU#kurta'&&r.items[1].Put?.Item?.id?.S==='ORDER#9001'&&equalRows(t?.items,expected)&&equalRows(tab(s,'checkout')?.items,expected);}},{text:'Current strong GetItem asli commit hua ORDER#9001 prove karta hai',check:s=>{const t=tab(s,'checkout'),r=t?.lastRead;return !!r&&r.op==='get-item'&&r.consistent&&r.revision===(t.revision||0)&&equalRows(r.items,[{id:'ORDER#9001',quantity:1}]);}}];
        return {title:'🖥️ Ek stock item; atomic checkout',goal:'<p>checkout table mein SKU#kurta available 1 hai. cat too-many.json aur checkout.json chalao. aws dynamodb transact-write-items --transact-items file://too-many.json --client-request-token checkout-failed chalao. Quantity 2 par TransactionCanceledException aana chahiye aur data waisa hi rehna chahiye. Phir aws dynamodb transact-write-items --transact-items file://checkout.json --client-request-token checkout-success se stock 0 + ORDER#9001 quantity 1 commit hota hai. Aakhri strong get-item se order ki asli commit hui row aani chahiye.</p><p>Stock/order ki alag writes, stock delete karna ya aadhi safalta nahi chalegi. Is limit wale fixed-clock simulator mein tokens 10 minute valid hain; billing/locking latency ka benchmark nahi.</p>',account:{region:'ap-south-1',tables:[{name:'checkout',partitionKey:'id',attributeTypes:{id:'S'},billing:'PAY_PER_REQUEST',status:'ACTIVE',items:initial}]},files:{'too-many.json':file(transaction(2)),'checkout.json':file(transaction(1))},solution,tasks,solutionErrors:{0:'TransactionCanceledException'},hints:['Quantity 2 stock 1 se zyada hai: transaction files dekho aur safal checkout se pehle "sab ya kuch nahi" wali failure prove karo.',...solution],success:AG.allOf(tasks),successText:'Fail hua quantity 2 stock/order ko waisa hi chhod gaya. Quantity 1 ne atomic tarike se stock 0/order 1 commit kiya; aakhri strong read ne asli order lautaya. Moto ke token replay ka farak aur fixed-clock simulator ki limits saaf likhi hain.'};})()}
    ]},
    success:['Access patterns aur na badalne wali primary key ki migration samjha sakta hoon','Round kiye units, peak ka hisaab aur hot key ka saboot compare kar sakta hoon','GSI/LSI ki consistency/projection aur Query/Scan pagination chun sakta hoon','Conditional writes, transactions, TTL/PITR/Streams aur global replicas ki limits alag pehchaan sakta hoon'],
    homework:'<p><b>Optional, sirf approved AWS sandbox mein (paisa lagega).</b> Pehle Region ke aaj ke daam/quotas, budget alarms aur IAM scope check karo. Unique naam wali temporary cart tables, asli jaisa bata hua traffic aur ek control kiya ek-key wala test use karo. Throttle ki wajah, p99, consumed units aur GSI backpressure naapo; shared production par load mat daalo. Conditional duplicate aur fail hua atomic checkout asli data se check karo. PITR on karo, asli restore range likho, nayi table mein restore karke rows compare karo; TTL ko app ke expiry check ke saath test karo. Chalte writers ke saath migration ko alag CDC/milaan/cutover drill maano. Cleanup: apni saari source/restore hui tables, backups/exports/S3 objects, alarms/roles aur optional cache/replicas hatao; billing check karo. Free tier ya turant expiry ka koi vaada nahi.</p>',
    cards:[
      {front:'Primary key wahin badal sakti hai?',back:'Nahi. Naye schema wali alag table, check kiya backfill/catch-up, control kiya cutover aur rollback. Poora HASH+RANGE combination unique hota hai.'},
      {front:'5 KB eventual read aur standard write?',back:'ceil(5/4) × 0.5 = 1 read unit; ceil(5/1) = 5 write units. Transactions standard ke 2× units lete hain.'},
      {front:'Hot key vs table ki kul capacity?',back:'Physical partition 3000 read/1000 write units/s tak ke liye bana hai. Traffic ka batna aur adaptive limits maayne rakhte hain; sirf alag keys kaafi nahi.'},
      {front:'Query filter read capacity bachata hai?',back:'Nahi. Filters 1 MB tak padhe page ke baad lagte hain. Khaali result par bhi LastEvaluatedKey se aage badho; matching keys/index use karo.'},
      {front:'GSI versus LSI?',back:'GSI: alag HASH, baad mein bhi ban sakta hai, eventual, alag provisioned capacity. LSI: same HASH, sirf table banate waqt, strong optional, capacity share/10 GB collection limit.'},
      {front:'Batch versus transaction?',back:'Batch: 25 puts/deletes, 16 MB, atomic nahi, UnprocessedItems retry karo. Transaction: 100 alag items, 4 MB, supported scope mein atomic, token 10 minute.'},
      {front:'TTL, Streams, PITR?',back:'TTL: Number epoch seconds, background mein delete. Streams: 24 ghante ke item badlav. PITR: 1–35 din, asli time range ke andar nayi table mein restore. Teen alag tools.'},
      {front:'MREC versus MRSC?',back:'MREC: async, last-writer-wins, sirf local transaction atomic. MRSC: Regions ke beech strong, 3 Region ki topology, abhi TTL/LSI/transactions nahi; GSI eventual. Mode badal nahi sakta.'}
    ]
  }]);
})();
